-- Carga de 80 camisetas. Ejecutar después de subir las imágenes con este script.
on conflict (id) do update set name=excluded.name, description=excluded.description, cat=excluded.cat, img=excluded.img, price=excluded.price, old=excluded.old, tag=excluded.tag, stock=excluded.stock, compatible_models=excluded.compatible_models, colors=excluded.colors, tier_prices=excluded.tier_prices;
